        .xd-header-tools{justify-content:flex-end;flex-wrap:wrap}
        .xd-top-link{display:inline-flex;align-items:center;justify-content:center;min-height:28px;padding:0;border:0;background:transparent;color:rgba(255,255,255,.82);font:inherit;font-size:12px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap;cursor:pointer}
        .xd-top-link.is-admin{padding:0 12px;border-radius:999px;background:var(--lime);color:#fff;box-shadow:0 8px 18px rgba(189,212,0,.26)}
        .xd-language-switcher{display:inline-flex;align-items:center;gap:4px;padding:3px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(255,255,255,.07)}
        .xd-language-switcher a{display:inline-flex;align-items:center;justify-content:center;min-width:34px;min-height:24px;border-radius:999px;color:rgba(255,255,255,.78);font-size:11px;font-weight:950;letter-spacing:.06em}
        .xd-language-switcher a.is-active{background:#fff;color:#101d28}
        .xd-header-inner{display:flex;align-items:center;justify-content:space-between;min-height:102px;gap:34px}
        .xd-logo{display:inline-flex;align-items:center;gap:11px;font-size:34px;font-weight:900;letter-spacing:-.06em;color:var(--ink)}
        .xd-logo-image{display:block;width:auto;max-width:156px;height:64px;object-fit:contain}
        .xd-logo-mark{position:relative;width:38px;height:50px;background:linear-gradient(135deg,var(--lime),#d9ec27);clip-path:polygon(50% 0,100% 22%,100% 100%,0 100%,0 22%)}
        .xd-logo-mark:before,.xd-logo-mark:after{content:"";position:absolute;background:#fff}.xd-logo-mark:before{left:9px;bottom:7px;width:20px;height:30px}.xd-logo-mark:after{left:14px;top:17px;width:10px;height:7px;box-shadow:0 11px 0 #fff}.xd-logo span{color:var(--lime)}
        .xd-nav{display:flex;align-items:center;justify-content:center;gap:0;min-width:0;flex:1}.xd-nav-item{position:relative}.xd-nav-link{display:inline-flex;align-items:center;gap:8px;padding:39px 21px;color:#344354;font-size:15px;font-weight:850;letter-spacing:.045em;text-transform:uppercase;white-space:nowrap}.xd-nav-caret{color:var(--lime-dark);font-size:12px;line-height:1;transition:transform .18s ease}.xd-nav-link.is-active,.xd-nav-link:hover,.xd-nav-item:hover>.xd-nav-link,.xd-nav-item:focus-within>.xd-nav-link{color:var(--lime-dark)}.xd-nav-item:hover>.xd-nav-link .xd-nav-caret,.xd-nav-item:focus-within>.xd-nav-link .xd-nav-caret{transform:rotate(180deg)}
        .xd-dropdown{position:absolute;top:100%;left:0;z-index:90;min-width:250px;padding:12px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);opacity:0;visibility:hidden;transform:translateY(12px);transition:opacity .18s ease,transform .18s ease,visibility .18s ease}.xd-nav-item:hover>.xd-dropdown,.xd-nav-item:focus-within>.xd-dropdown{opacity:1;visibility:visible;transform:translateY(0)}.xd-dropdown-item{position:relative}.xd-dropdown-link{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 14px;border-left:3px solid transparent;color:#53606b;font-size:14px;font-weight:800;line-height:1.35}.xd-dropdown-link:hover,.xd-dropdown-item:focus-within>.xd-dropdown-link{background:#f7f9ee;border-left-color:var(--lime);color:var(--ink)}.xd-subdropdown{position:absolute;top:0;left:calc(100% + 10px);z-index:91;min-width:230px;padding:10px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);opacity:0;visibility:hidden;transform:translateX(-8px);transition:opacity .18s ease,transform .18s ease,visibility .18s ease}.xd-dropdown-item:hover>.xd-subdropdown,.xd-dropdown-item:focus-within>.xd-subdropdown{opacity:1;visibility:visible;transform:translateX(0)}
        .xd-header-actions{display:flex;align-items:center;gap:12px;flex:0 0 auto}.xd-cart-link{display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;border:1px solid rgba(38,56,74,.14);border-radius:4px;background:#fff;color:var(--ink);box-shadow:0 12px 24px rgba(16,29,40,.08);transition:.2s ease}.xd-cart-link svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.xd-cart-link:hover{border-color:var(--lime);background:var(--lime);color:#fff;transform:translateY(-1px)}.xd-login-button{display:inline-flex;align-items:center;justify-content:center;min-height:58px;padding:0 22px;border:1px solid rgba(38,56,74,.14);border-radius:4px;background:#fff;color:var(--ink);box-shadow:0 12px 24px rgba(16,29,40,.08);font:inherit;font-size:14px;font-weight:900;letter-spacing:.045em;text-transform:uppercase;white-space:nowrap;cursor:pointer}.xd-login-button:hover{border-color:var(--lime);color:var(--lime-dark);transform:translateY(-1px)}
        .xd-floating-hotline{position:fixed;right:28px;bottom:28px;z-index:180;display:inline-flex;align-items:center;gap:12px;min-height:60px;padding:10px 20px 10px 10px;border-radius:999px;background:linear-gradient(135deg,var(--lime),#d7ec24);color:#fff;box-shadow:0 18px 42px rgba(159,181,0,.38);font-weight:900;text-decoration:none;isolation:isolate;transition:transform .2s ease,box-shadow .2s ease}.xd-floating-hotline:before{content:"";position:absolute;inset:-7px;z-index:-1;border:2px solid rgba(189,212,0,.48);border-radius:inherit;animation:xd-hotline-pulse 1.8s ease-out infinite}.xd-floating-hotline:hover{transform:translateY(-3px);box-shadow:0 24px 54px rgba(159,181,0,.48)}.xd-floating-hotline__icon{display:grid;place-items:center;width:42px;height:42px;border-radius:999px;background:#fff;color:var(--ink);box-shadow:0 8px 18px rgba(16,29,40,.14)}.xd-floating-hotline__icon svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.xd-floating-hotline__copy{display:grid;line-height:1.05}.xd-floating-hotline__copy span{color:rgba(255,255,255,.84);font-size:11px;font-weight:950;letter-spacing:.09em;text-transform:uppercase}.xd-floating-hotline__copy strong{font-size:18px;letter-spacing:.025em;text-shadow:0 2px 10px rgba(0,0,0,.16);white-space:nowrap}@keyframes xd-hotline-pulse{0%{opacity:.9;transform:scale(.98)}70%,100%{opacity:0;transform:scale(1.16)}}
        .xd-mobile-menu-toggle{display:none;align-items:center;justify-content:center;gap:9px;min-height:44px;padding:0 16px;border:1px solid rgba(38,56,74,.12);border-radius:999px;background:#101d28;color:#fff;font:inherit;font-size:13px;font-weight:950;letter-spacing:.05em;text-transform:uppercase;box-shadow:0 14px 28px rgba(16,29,40,.16);cursor:pointer}.xd-mobile-menu-toggle:before{content:"";width:16px;height:2px;background:currentColor;box-shadow:0 -6px 0 currentColor,0 6px 0 currentColor}.xd-mobile-panel[hidden]{display:none!important}.xd-mobile-panel{display:none}.xd-mobile-list,.xd-mobile-children{display:grid;gap:8px;margin:0;padding:0;list-style:none}.xd-mobile-link,.xd-mobile-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:48px;padding:0 14px;border:1px solid #edf0f2;border-radius:14px;background:#fff;color:var(--ink);font-size:14px;font-weight:900;text-transform:uppercase}.xd-mobile-link.is-active,.xd-mobile-summary.is-active{border-color:var(--lime);background:#f8fbde;color:var(--lime-dark)}.xd-mobile-item details{display:grid;gap:8px}.xd-mobile-summary{cursor:pointer;list-style:none}.xd-mobile-summary::-webkit-details-marker{display:none}.xd-mobile-summary:after{content:"+";display:grid;place-items:center;width:24px;height:24px;border-radius:999px;background:#f2f5ed;color:var(--lime-dark);font-size:17px;line-height:1}.xd-mobile-item details[open]>.xd-mobile-summary:after{content:"-";background:var(--lime);color:#fff}.xd-mobile-children{margin:8px 0 0 14px;padding-left:10px;border-left:2px solid #e8efcf}.xd-mobile-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px;padding-top:14px;border-top:1px solid #edf0f2}.xd-mobile-actions .xd-login-button{width:100%;min-height:48px;justify-content:center;border-radius:14px;padding:0 12px;font-size:13px}.xd-mobile-language{grid-column:1/-1;display:flex;align-items:center;gap:8px}.xd-mobile-language a{display:inline-flex;align-items:center